package main

import "fmt"

var romanToIntTable = map[string]int{}

func init() {
	thousands := []string{"", "M", "MM", "MMM"}
	hundreds := []string{"", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM"}
	tens := []string{"", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"}
	ones := []string{"", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"}

	for t := 0; t < len(thousands); t++ {
		for h := 0; h < len(hundreds); h++ {
			for te := 0; te < len(tens); te++ {
				for o := 0; o < len(ones); o++ {
					value := t*1000 + h*100 + te*10 + o
					if value == 0 {
						continue
					}
					romanToIntTable[thousands[t]+hundreds[h]+tens[te]+ones[o]] = value
				}
			}
		}
	}
}

func RomanToInt(s string) (int, error) {
	if value, ok := romanToIntTable[s]; ok {
		return value, nil
	}
	return 0, fmt.Errorf("invalid Roman numeral: %q", s)
}
