fn compress(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut it = s.chars();

    if let Some(mut c) = it.next() {
        let mut count: usize = 1;

        for next in it {
            if next == c {
                count += 1;
            } else {
                out.push(c);
                if count > 1 {
                    out.push_str(&count.to_string());
                }
                c = next;
                count = 1;
            }
        }

        out.push(c);
        if count > 1 {
            out.push_str(&count.to_string());
        }
    }

    out
}
