fn eval_rpn(tokens: &[&str]) -> Option<i64> {
    let mut stack: Vec<i64> = Vec::new();

    for &token in tokens {
        match token {
            "+" | "-" | "*" | "/" => {
                let right = stack.pop()?;
                let left = stack.pop()?;

                let value = match token {
                    "+" => left.checked_add(right)?,
                    "-" => left.checked_sub(right)?,
                    "*" => left.checked_mul(right)?,
                    "/" => left.checked_div(right)?,
                    _ => unreachable!(),
                };

                stack.push(value);
            }
            _ => {
                let value: i64 = token.parse().ok()?;
                stack.push(value);
            }
        }
    }

    if stack.len() == 1 {
        Some(stack.pop()?)
    } else {
        None
    }
}
